-- Generated by Ingestron from flows/crm.yaml (table accounts). Do not edit: change the definitions and generate again.
-- Changes as received, each read once.
CREATE OR REFRESH STREAMING TABLE `dev`.`bronze`.`accounts_changes`
AS SELECT * FROM STREAM read_files(
  '/Volumes/dev/landing/crm/changes/accounts',
  format => 'json',
  schemaHints => '`account_id` STRING, `name` STRING, `segment` STRING, `changed_at` TIMESTAMP, `operation` STRING',
  schemaEvolutionMode => 'addNewColumns'
);

-- The current rows, kept by key.
CREATE OR REFRESH STREAMING TABLE `dev`.`bronze`.`accounts` (
  CONSTRAINT `account_id_not_null` EXPECT (`account_id` IS NOT NULL),
  CONSTRAINT `changed_at_not_null` EXPECT (`changed_at` IS NOT NULL)
)
COMMENT 'Customer accounts, current version only.'
CLUSTER BY AUTO;

CREATE FLOW `accounts_cdc`
AS AUTO CDC INTO `dev`.`bronze`.`accounts`
FROM STREAM(`dev`.`bronze`.`accounts_changes`)
KEYS (`account_id`)
APPLY AS DELETE WHEN operation = 'DELETE'
SEQUENCE BY `changed_at`
COLUMNS * EXCEPT (`operation`)
STORED AS SCD TYPE 1;
